(5954525, 869703, 46314, '<td valign="top">Nice idea.</td>', 'Nice idea.', '2010-04-19 07:36:23.000000', NULL, 1),
(5954528, 867864, 46314, '<td valign="top">I like the orange hues throughout. The composition isn''t quite spot on though. Those two flowers in the foreground are a bit distracting though. Sometimes the rule of thirds shouldn''t be broken.</td>', 'I like the orange hues throughout. The composition isn''t quite spot on though. Those two flowers in the foreground are a bit distracting though. Sometimes the rule of thirds shouldn''t be broken.', '2010-04-19 07:37:32.000000', NULL, 1),
(5954531, 869633, 46314, '<td valign="top">Bizarre. The trees are actually captured quite nicely, but that balloon is fiercely unnattractive.</td>', 'Bizarre. The trees are actually captured quite nicely, but that balloon is fiercely unnattractive.', '2010-04-19 07:38:22.000000', NULL, 1),
(5954533, 868911, 46314, '<td valign="top">Stopped motion balloon burst #2: nice timing, but the composition is a bit off.</td>', 'Stopped motion balloon burst #2: nice timing, but the composition is a bit off.', '2010-04-19 07:40:16.000000', NULL, 1),
(5954535, 867510, 46314, '<td valign="top">Nice shot. I find the colour palette a bit un-coordinated though. Maybe if you''d used a more uniform set of sunset hues it would have complimented the composition more.</td>', 'Nice shot. I find the colour palette a bit un-coordinated though. Maybe if you''d used a more uniform set of sunset hues it would have complimented the composition more.', '2010-04-19 07:40:24.000000', NULL, 1),
