(5954645, 870109, 46314, '<td valign="top">Nice silhouette. But the dark tones and grays make the happiness of the title seem ironic.</td>', 'Nice silhouette. But the dark tones and grays make the happiness of the title seem ironic.', '2010-04-19 08:34:00.000000', NULL, 1),
(5954646, 869058, 46314, '<td valign="top">Nice idea. Well executed.</td>', 'Nice idea. Well executed.', '2010-04-19 08:34:19.000000', NULL, 1),
(5954648, 868849, 46314, '<td valign="top">Nice colours.</td>', 'Nice colours.', '2010-04-19 08:34:35.000000', NULL, 1),
(5954649, 869967, 46314, '<td valign="top">Funny execution of this idea.</td>', 'Funny execution of this idea.', '2010-04-19 08:34:55.000000', NULL, 1),
