(5954652, 869551, 46314, '<td valign="top">Nice image. Has a certain appeal to it. You controlled the lighting well.</td>', 'Nice image. Has a certain appeal to it. You controlled the lighting well.', '2010-04-19 08:36:05.000000', NULL, 1),
(5954653, 869630, 46314, '<td valign="top">Awesome. I love the repeating pattern of the trees in the background, and I like how you controlled to tones to keep those lovely pastel colours.</td>', 'Awesome. I love the repeating pattern of the trees in the background, and I like how you controlled to tones to keep those lovely pastel colours.', '2010-04-19 08:36:19.000000', NULL, 1),
(5954654, 867499, 46314, '<td valign="top">Goth girl with balloons #1. Nice textures.</td>', 'Goth girl with balloons #1. Nice textures.', '2010-04-19 08:36:28.000000', NULL, 1),
(5954656, 870166, 46314, '<td valign="top">Nice family snap.</td>', 'Nice family snap.', '2010-04-19 08:36:50.000000', NULL, 1),
(5954660, 870027, 46314, '<td valign="top">Colourful.</td>', 'Colourful.', '2010-04-19 08:37:40.000000', NULL, 1),
(5954661, 867880, 46314, '<td valign="top">Funny title.</td>', 'Funny title.', '2010-04-19 08:37:52.000000', NULL, 1),
(5954666, 870018, 46314, '<td valign="top">Nice idea, but the execution of it just doesn''t grab me. Maybe it''s the composition. I''ll have to think about it.</td>', 'Nice idea, but the execution of it just doesn''t grab me. Maybe it''s the composition. I''ll have to think about it.', '2010-04-19 08:38:47.000000', NULL, 1),
(5954668, 869660, 46314, '<td valign="top">That is so scary. And old guy turns up in a bunch of pink balloons! And he''s the one with the shocked look on his face?!</td>', 'That is so scary. And old guy turns up in a bunch of pink balloons! And he''s the one with the shocked look on his face?!', '2010-04-19 08:40:18.000000', NULL, 1),
(5954669, 869983, 89341, '<td valign="top">lol, great expression</td>', 'lol, great expression', '2010-04-19 08:40:37.000000', NULL, 1),
(5954670, 870139, 46314, '<td valign="top">The subject of the photo conveys the feeling of joy well, but I think it would have popped a bit more if the colours had been more vibrant in the background.</td>', 'The subject of the photo conveys the feeling of joy well, but I think it would have popped a bit more if the colours had been more vibrant in the background.', '2010-04-19 08:41:26.000000', NULL, 1),
(5954671, 869776, 114225, '<td valign="top">I like it, but I wonder if an even faster shutter should have looked nicer.</td>', 'I like it, but I wonder if an even faster shutter should have looked nicer.', '2010-04-19 08:41:55.000000', NULL, 1),
(5954672, 869262, 46314, '<td valign="top">Nice use of colours and lighting to add to the wondrous innocence of the child.</td>', 'Nice use of colours and lighting to add to the wondrous innocence of the child.', '2010-04-19 08:41:56.000000', NULL, 1),
(5954673, 868701, 46314, '<td valign="top">So weird. Funny. But weird.</td>', 'So weird. Funny. But weird.', '2010-04-19 08:42:18.000000', NULL, 1),
(5954675, 870020, 46314, '<td valign="top">Well, you could always go off to see the wizard! Oh no, wait - you don''t have legs either...</td>', 'Well, you could always go off to see the wizard! Oh no, wait - you don''t have legs either...', '2010-04-19 08:43:11.000000', NULL, 1),
(5954676, 867842, 46314, '<td valign="top">Tunnel? Still, I like it.</td>', 'Tunnel? Still, I like it.', '2010-04-19 08:43:44.000000', NULL, 1),
(5954679, 869875, 114225, '<td valign="top">A neat perspective. I''m not sure that I understand the title.</td>', 'A neat perspective. I''m not sure that I understand the title.', '2010-04-19 08:44:03.000000', NULL, 1),
(5954683, 869270, 46314, '<td valign="top">Horrible. But at least you have a sense of humour, and it''s well lit. Still, horrible.</td>', 'Horrible. But at least you have a sense of humour, and it''s well lit. Still, horrible.', '2010-04-19 08:44:47.000000', NULL, 1),
(5954684, 868703, 114225, '<td valign="top">Nice execution on a great idea. I would have liked to see a bit more of the balloon body.</td>', 'Nice execution on a great idea. I would have liked to see a bit more of the balloon body.', '2010-04-19 08:45:18.000000', NULL, 1),
(5954685, 869751, 46314, '<td valign="top">Very funny idea. Nicely executed and I like the title.</td>', 'Very funny idea. Nicely executed and I like the title.', '2010-04-19 08:45:40.000000', NULL, 1),
(5954686, 870148, 46314, '<td valign="top">Interesting idea. I love the stockings.</td>', 'Interesting idea. I love the stockings.', '2010-04-19 08:45:57.000000', NULL, 1),
(5954689, 867960, 46314, '<td valign="top">Haha. Awesome! Brilliantly executed.</td>', 'Haha. Awesome! Brilliantly executed.', '2010-04-19 08:46:39.000000', NULL, 1),
(5954690, 868654, 114225, '<td valign="top">I like the idea. I think it could have benefitted from more light so we could clearly see the entire water drop shape.</td>', 'I like the idea. I think it could have benefitted from more light so we could clearly see the entire water drop shape.', '2010-04-19 08:46:46.000000', NULL, 1),
(5954693, 869815, 46314, '<td valign="top">Fairly odd.</td>', 'Fairly odd.', '2010-04-19 08:47:18.000000', NULL, 1),
(5954694, 869270, 114225, '<td valign="top">Made me laugh with my childish sense of humor :)</td>', 'Made me laugh with my childish sense of humor :)', '2010-04-19 08:47:24.000000', NULL, 1),
(5954695, 870009, 46314, '<td valign="top">Don''t like the composition.</td>', 'Don''t like the composition.', '2010-04-19 08:47:36.000000', NULL, 1),
(5954699, 869721, 46314, '<td valign="top">Not that high-key though... more like light grey...</td>', 'Not that high-key though... more like light grey...', '2010-04-19 08:48:05.000000', NULL, 1),
(5954700, 869967, 114225, '<td valign="top">Wow, that''s kind of freaky.</td>', 'Wow, that''s kind of freaky.', '2010-04-19 08:48:32.000000', NULL, 1),
(5954703, 869873, 114225, '<td valign="top">Hehe, I love puns in the titles.</td>', 'Hehe, I love puns in the titles.', '2010-04-19 08:49:54.000000', NULL, 1),
(5954706, 867960, 114225, '<td valign="top">Very creative. I would have liked it a bit more if the white bottom wasn''t so eye hurtingly bright, but I didn''t vote it down any for that.</td>', 'Very creative. I would have liked it a bit more if the white bottom wasn''t so eye hurtingly bright, but I didn''t vote it down any for that.', '2010-04-19 08:51:03.000000', NULL, 1),
(5954709, 870021, 114225, '<td valign="top">Good idea for this time of year, just not well executed in my opinion. The lighting is very harsh, and the bear takes center stage as the subject (can barely see the balloons).</td>', 'Good idea for this time of year, just not well executed in my opinion. The lighting is very harsh, and the bear takes center stage as the subject (can barely see the balloons).', '2010-04-19 08:53:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5954711, 869787, 114225, '<td valign="top">Nicely done. Very scary.</td>', 'Nicely done. Very scary.', '2010-04-19 08:53:46.000000', NULL, 1),
(5954718, 869248, 114225, '<td valign="top">Hmmm, good idea, but I voted it down a bit due to a couple big things. First, it feels out of focus or grainy. Second, the entire top of the shot should have been filled with balloons.</td>', 'Hmmm, good idea, but I voted it down a bit due to a couple big things. First, it feels out of focus or grainy. Second, the entire top of the shot should have been filled with balloons.', '2010-04-19 08:56:43.000000', NULL, 1),
(5954720, 869848, 46314, '<td valign="top">Nice abstract - looks like gnashing teeth inside a mouth.</td>', 'Nice abstract - looks like gnashing teeth inside a mouth.', '2010-04-19 08:58:14.000000', NULL, 1),
(5954723, 868110, 114225, '<td valign="top">Oh man, this could have been a completely perfect shot if the lake had a reflection of the balloon. But still, nicely done.</td>', 'Oh man, this could have been a completely perfect shot if the lake had a reflection of the balloon. But still, nicely done.', '2010-04-19 08:58:46.000000', NULL, 1),
(5954725, 868535, 46314, '<td valign="top">Shame. Poor balloon. I''d like to see what he ends up like four days later...</td>', 'Shame. Poor balloon. I''d like to see what he ends up like four days later...', '2010-04-19 08:59:10.000000', NULL, 1),
(5954727, 868828, 46314, '<td valign="top">Wow. Interesting concept. Love the make-up</td>', 'Wow. Interesting concept. Love the make-up', '2010-04-19 08:59:33.000000', NULL, 1),
(5954729, 869660, 114225, '<td valign="top">Well done. The focus on the face is crisp, which I learned was pretty hard to do through a balloon :)</td>', 'Well done. The focus on the face is crisp, which I learned was pretty hard to do through a balloon :)', '2010-04-19 09:00:13.000000', NULL, 1),
