(5955766, 869665, 6870, '<td valign="top">Looks like the salt flats in Utah. You must live near me! I like the composition here, and you''ve used the negative space of the flats well. With a title like "thirsty", it might also work to have a goblet of water or something. Nice work.</td>', 'Looks like the salt flats in Utah. You must live near me! I like the composition here, and you''ve used the negative space of the flats well. With a title like "thirsty", it might also work to have a goblet of water or something. Nice work.', '2010-04-19 14:45:52.000000', NULL, 1),
(5955770, 869704, 6870, '<td valign="top">This works really nicely for me. There is lots of color in the image, and the balloons and woman are particularly engaging with the lines of the road and the grey framing from the road.</td>', 'This works really nicely for me. There is lots of color in the image, and the balloons and woman are particularly engaging with the lines of the road and the grey framing from the road.', '2010-04-19 14:47:13.000000', NULL, 1),
(5955773, 868535, 6870, '<td valign="top">Simple and effective. Nice exposure and lighting, too.</td>', 'Simple and effective. Nice exposure and lighting, too.', '2010-04-19 14:48:02.000000', NULL, 1),
(5955787, 868288, 6870, '<td valign="top">This image creates an intriguing contrast between the happy balloons and the despondently empty room, so it''s a clear communication, and effective. 9</td>', 'This image creates an intriguing contrast between the happy balloons and the despondently empty room, so it''s a clear communication, and effective. 9', '2010-04-19 14:54:49.000000', NULL, 1),
