(5956572, 869270, 43774, '<td valign="top">Could this be by <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=35357" rel="nofollow" target="_blank">Strikeslip</a> I wonder?</td>', 'Could this be by  Strikeslip I wonder?', '2010-04-19 22:05:20.000000', NULL, 1),
(5956574, 868571, 61971, '<td valign="top">I am going to comment on this as if it were in the zen shot, since I think that may be where you meant to enter it. <br/> <br/>What a catch!! I like the color and of course the symmetry. I feel like it could be a tad sharper though. In zen on it''s own merits I would have given a 6 or 7. <br/> <br/>In the balloon challenge (in case I''m wrong and this is where you meant to submit to) I am giving this a 3 because I can''t really tell that a balloon made this shape.</td>', 'I am going to comment on this as if it were in the zen shot, since I think that may be where you meant to enter it.  What a catch!! I like the color and of course the symmetry. I feel like it could be a tad sharper though. In zen on it''s own merits I would have given a 6 or 7.  In the balloon challenge (in case I''m wrong and this is where you meant to submit to) I am giving this a 3 because I can''t really tell that a balloon made this shape.', '2010-04-19 22:06:13.000000', NULL, 1),
(5956578, 869787, 57447, '<td valign="top">Good advertisement for a circus or something odd.</td>', 'Good advertisement for a circus or something odd.', '2010-04-19 22:06:56.000000', NULL, 1),
