(5956878, 868288, 25313, '<td valign="top">love the room with great tones. probably even better without the balloons. 8</td>', 'love the room with great tones. probably even better without the balloons. 8', '2010-04-20 00:14:01.000000', NULL, 1),
(5956881, 868925, 25313, '<td valign="top">makes you wonder how this was done. 6</td>', 'makes you wonder how this was done. 6', '2010-04-20 00:15:02.000000', NULL, 1),
