(5956896, 870148, 25313, '<td valign="top">pov works well.</td>', 'pov works well.', '2010-04-20 00:20:48.000000', NULL, 1),
(5956900, 870079, 61971, '<td valign="top">I like the theme, this would have been better for me if you had something to reflect the light into the shadows on his face which would have helped with the noise. I also feel that the background is a little busy. Cute kid though :)</td>', 'I like the theme, this would have been better for me if you had something to reflect the light into the shadows on his face which would have helped with the noise. I also feel that the background is a little busy. Cute kid though :)', '2010-04-20 00:21:51.000000', NULL, 1),
(5956903, 869541, 61971, '<td valign="top">The title and processing are over my head, like it''s a book you are quoting that I have not read. The balloon looks more like a bubble to me and I guess because I don''t get the title I can''t appreciate the selective desat and kelly green treatment. Sorry.</td>', 'The title and processing are over my head, like it''s a book you are quoting that I have not read. The balloon looks more like a bubble to me and I guess because I don''t get the title I can''t appreciate the selective desat and kelly green treatment. Sorry.', '2010-04-20 00:22:51.000000', NULL, 1),
(5956904, 868733, 61971, '<td valign="top">Nice looking pup, I would have loved to see this with his/her face surrounded by the balloons and more light on the face.</td>', 'Nice looking pup, I would have loved to see this with his/her face surrounded by the balloons and more light on the face.', '2010-04-20 00:22:54.000000', NULL, 1),
(5956910, 868857, 115307, '<td valign="top">Nicely photographed but otherwise uninteresting. Whatever is behind the balloons is a little distracting.</td>', 'Nicely photographed but otherwise uninteresting. Whatever is behind the balloons is a little distracting.', '2010-04-20 00:27:09.000000', NULL, 1),
(5956911, 868853, 25313, '<td valign="top">this could have worked for the model challenge. this lighting is tough. perfect execution! 8</td>', 'this could have worked for the model challenge. this lighting is tough. perfect execution! 8', '2010-04-20 00:27:35.000000', NULL, 1),
