(5963563, 869691, 113278, '<td valign="top">Great shot. 10, one of my top 3 picks for the challenge.</td>', 'Great shot. 10, one of my top 3 picks for the challenge.', '2010-04-22 13:37:02.000000', NULL, 1),
(5963566, 869212, 113278, '<td valign="top">Beautifully done. Great lighting and comp and it tells a story (or it at least implies a story that each viewer can interpet to themselves) Really nice work. One of my top 3 for the challenge.</td>', 'Beautifully done. Great lighting and comp and it tells a story (or it at least implies a story that each viewer can interpet to themselves) Really nice work. One of my top 3 for the challenge.', '2010-04-22 13:38:22.000000', NULL, 1),
