INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5967853, 869949, 68573, '<td valign="top">This is an absolute ''wow'' shot. Intriguing,innovative and interesting take on the challenge. As an afterthought - Maybe you could have lighted it a tad differently to avoid those highlight patches on the  neck balloons and the sides of the forehead. A stunner and a ribbon contender nonetheless</td>', 'This is an absolute ''wow'' shot. Intriguing,innovative and interesting take on the challenge. As an afterthought - Maybe you could have lighted it a tad differently to avoid those highlight patches on the  neck balloons and the sides of the forehead. A stunner and a ribbon contender nonetheless', '2010-04-25 12:41:19.000000', NULL, 1),
(5967857, 869338, 68573, '<td valign="top">Great setup and very interesting take - well executed too</td>', 'Great setup and very interesting take - well executed too', '2010-04-25 12:43:11.000000', NULL, 1),
(5967863, 869868, 68573, '<td valign="top">:)</td>', ':)', '2010-04-25 12:45:53.000000', NULL, 1),
(5967870, 867924, 100301, '<td valign="top">My pick for blue.  LOVE IT.</td>', 'My pick for blue.  LOVE IT.', '2010-04-25 12:49:14.000000', NULL, 1),
(5967994, 869620, 83313, '<td valign="top">Very unusual, but the harsh lighting lets it down, I''m afraid.</td>', 'Very unusual, but the harsh lighting lets it down, I''m afraid.', '2010-04-25 13:47:17.000000', NULL, 1),
(5967997, 868967, 83313, '<td valign="top">I have to take extra effort to evaluate street photography differently than the contrived shots. Perhaps there is some tilt that works against this, but you may not have been able to fix that and keep all the elements in the frame.</td>', 'I have to take extra effort to evaluate street photography differently than the contrived shots. Perhaps there is some tilt that works against this, but you may not have been able to fix that and keep all the elements in the frame.', '2010-04-25 13:48:53.000000', NULL, 1),
(5967999, 870168, 83313, '<td valign="top">Hi, hon! (No vote, comment only)</td>', 'Hi, hon! (No vote, comment only)', '2010-04-25 13:49:49.000000', NULL, 1),
(5968004, 869716, 83313, '<td valign="top">That''s a sure way to get little ones to perform for the camera!</td>', 'That''s a sure way to get little ones to perform for the camera!', '2010-04-25 13:50:58.000000', NULL, 1),
(5968005, 869788, 83313, '<td valign="top">I almost missed the balloon.</td>', 'I almost missed the balloon.', '2010-04-25 13:51:16.000000', NULL, 1),
(5968007, 869877, 83313, '<td valign="top">Goofy faces always get extra pointage from me. I just love goofy faces. (Yes, personal appeal is a factor in voting, I won''t deny it.)</td>', 'Goofy faces always get extra pointage from me. I just love goofy faces. (Yes, personal appeal is a factor in voting, I won''t deny it.)', '2010-04-25 13:53:11.000000', NULL, 1),
(5968008, 869051, 83313, '<td valign="top">Basic, simple and well done. Very effective use of lighting. I expect this to place high. I should learn to take the visually simple approach more often.</td>', 'Basic, simple and well done. Very effective use of lighting. I expect this to place high. I should learn to take the visually simple approach more often.', '2010-04-25 13:54:29.000000', NULL, 1),
(5968011, 869542, 83313, '<td valign="top">Seems slightly on the snapshotty side, but I really like the story told by this.</td>', 'Seems slightly on the snapshotty side, but I really like the story told by this.', '2010-04-25 13:55:25.000000', NULL, 1),
(5968017, 870021, 83313, '<td valign="top">Kind of dark and nothing really jumps out at me. I''m not sure the low saturation against a dark background works for me. I do see some thought and effort here, however.</td>', 'Kind of dark and nothing really jumps out at me. I''m not sure the low saturation against a dark background works for me. I do see some thought and effort here, however.', '2010-04-25 13:56:56.000000', NULL, 1),
(5968023, 869633, 83313, '<td valign="top">I have one of these. I bought the dragon. Not really a balloon, but a punching ball. No body else will probably know that unless that have bought one.</td>', 'I have one of these. I bought the dragon. Not really a balloon, but a punching ball. No body else will probably know that unless that have bought one.', '2010-04-25 13:59:11.000000', NULL, 1),
(5968027, 869077, 83313, '<td valign="top">The expected shot in this challenge. I''ll be surprised if I don''t encounter a variation of this at least a dozen times. No extra points from me for originality, but it''s very well shot and should do well.</td>', 'The expected shot in this challenge. I''ll be surprised if I don''t encounter a variation of this at least a dozen times. No extra points from me for originality, but it''s very well shot and should do well.', '2010-04-25 14:00:35.000000', NULL, 1),
(5968028, 870143, 83313, '<td valign="top">Extra pointage from me for originality and pure weirdness.</td>', 'Extra pointage from me for originality and pure weirdness.', '2010-04-25 14:01:39.000000', NULL, 1),
(5968034, 869634, 83313, '<td valign="top">Not coming off well with me, I''m afraid. Soft and grainy overall, flat lighting and the model is not posed in a flattering manner. Should have pulled down her top a little.</td>', 'Not coming off well with me, I''m afraid. Soft and grainy overall, flat lighting and the model is not posed in a flattering manner. Should have pulled down her top a little.', '2010-04-25 14:04:02.000000', NULL, 1),
(5968037, 869535, 66709, '<td valign="top">This should win hand down!!!!!</td>', 'This should win hand down!!!!!', '2010-04-25 14:04:44.000000', NULL, 1),
(5968038, 870170, 83313, '<td valign="top">I like the abstract approach you used her. I''ll be interested in seeing where is places. It gets a high vote from me.</td>', 'I like the abstract approach you used her. I''ll be interested in seeing where is places. It gets a high vote from me.', '2010-04-25 14:04:45.000000', NULL, 1),
(5968096, 869061, 75618, '<td valign="top">My personal favorite in the challenge. Funny how the first thing I noticed was the wedding ring haha...</td>', 'My personal favorite in the challenge. Funny how the first thing I noticed was the wedding ring haha...', '2010-04-25 14:41:37.000000', NULL, 1),
(5968103, 868019, 75618, '<td valign="top">Looks like a CGI still. One of my favorites in the challenge.</td>', 'Looks like a CGI still. One of my favorites in the challenge.', '2010-04-25 14:46:29.000000', NULL, 1),
(5968125, 869575, 75618, '<td valign="top">Not really a fan of selective desaturation but works wonderfully here.</td>', 'Not really a fan of selective desaturation but works wonderfully here.', '2010-04-25 14:55:16.000000', NULL, 1),
(5968163, 869665, 99708, '<td valign="top">Very fun picture.  The contrast of the baloons and the snow (?) is beautiful, and the captured color in the shadows ins a wonderful detail.  Good job!</td>', 'Very fun picture.  The contrast of the baloons and the snow (?) is beautiful, and the captured color in the shadows ins a wonderful detail.  Good job!', '2010-04-25 15:17:31.000000', NULL, 1),
(5968172, 869541, 99708, '<td valign="top">Title is a bit long and confusing - but we don''t judge on titles.  I''m finding the white strip in the bg and the ice in the corner a bit distracting.  Is that ice?  However, I do like the balloon and what appears to be a halo around it.</td>', 'Title is a bit long and confusing - but we don''t judge on titles.  I''m finding the white strip in the bg and the ice in the corner a bit distracting.  Is that ice?  However, I do like the balloon and what appears to be a halo around it.', '2010-04-25 15:20:59.000000', NULL, 1),
(5968174, 867649, 99708, '<td valign="top">Adorable.</td>', 'Adorable.', '2010-04-25 15:23:12.000000', NULL, 1),
(5968177, 869904, 99708, '<td valign="top">Nice job.  I like the simplicity in the shot, not over thought.  Focus, composition, etc - it''s all good.</td>', 'Nice job.  I like the simplicity in the shot, not over thought.  Focus, composition, etc - it''s all good.', '2010-04-25 15:25:10.000000', NULL, 1),
